const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-72.22, -39.28]); // Villarrica, Chile
    const aoi = point.buffer(1000); // 1km buffer around the point
    const scale = 5000; // CHIRPS native resolution is ~5.5km

    const date2021 = {start: '2021-01-01', end: '2021-12-31'};
    const date2016 = {start: '2016-01-01', end: '2016-12-31'}; // 5 years prior

    // 2. Data Acquisition & Check
    const dataset = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

    const col2021 = dataset.filterDate(date2021.start, date2021.end);
    const col2016 = dataset.filterDate(date2016.start, date2016.end);

    const size2021 = col2021.size().getInfo();
    const size2016 = col2016.size().getInfo();

    if (size2021 === 0 || size2016 === 0) {
        console.log(`Image count 2021: ${size2021}`);
        console.log(`Image count 2016: ${size2016}`);
        console.log("Empty Collection: No images found for one or both periods.");
        console.log("A"); // C1
        return;
    }

    // 3. Processing: Calculate total annual rainfall
    const totalRain2021 = col2021.select('precipitation').sum();
    const totalRain2016 = col2016.select('precipitation').sum();

    // 4. Calculation & Validation
    const rainfall2021Result = totalRain2021.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('precipitation');

    const rainfall2016Result = totalRain2016.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('precipitation');

    // Check for calculation failure (C3)
    const rainfall2021 = rainfall2021Result.getInfo();
    const rainfall2016 = rainfall2016Result.getInfo();

    if (rainfall2021 === null || rainfall2016 === null) {
        console.log(`Rainfall 2021: ${rainfall2021}`);
        console.log(`Rainfall 2016: ${rainfall2016}`);
        console.log("Calculation Failure: Result was null.");
        console.log("C3");
        return;
    }

    // Check for no valid pixels (C2) - less likely with CHIRPS but good practice
    const count2021 = totalRain2021.reduceRegion({reducer: ee.Reducer.count(), geometry: aoi, scale: scale}).get('precipitation').getInfo();
    const count2016 = totalRain2016.reduceRegion({reducer: ee.Reducer.count(), geometry: aoi, scale: scale}).get('precipitation').getInfo();

    if (count2021 === 0 || count2016 === 0) {
        console.log(`Valid pixel count 2021: ${count2021}`);
        console.log(`Valid pixel count 2016: ${count2016}`);
        console.log("No Valid Pixels: No data available for the specified location.");
        console.log("C2");
        return;
    }

    // 5. Final Answer
    console.log(`Image count 2021: ${size2021}`);
    console.log(`Image count 2016: ${size2016}`);
    console.log(`Total Rainfall 2021 (mm): ${rainfall2021.toFixed(2)}`);
    console.log(`Total Rainfall 2016 (mm): ${rainfall2016.toFixed(2)}`);

    if (rainfall2021 > rainfall2016) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e}`);
    console.log("D");
  }
}

initEE();
